// TypeScript: Thay đổi theme động tại Client Runtime không cần reload
export function toggleAppTheme(theme: 'light' | 'dark'): void {
  document.documentElement.setAttribute('data-theme', theme);
  localStorage.setItem('user-theme-preference', theme);
}

export function setDynamicBrandColor(hexColor: string): void {
  // Can thiệp trực tiếp vào CSS Variable của :root
  document.documentElement.style.setProperty('--accent-color', hexColor);
}

// Accordion Trigger Component chuẩn Accessibility WCAG 2.1 AA
interface AccordionProps {
  title: string;
  panelId: string;
  isExpanded: boolean;
  onToggle: () => void;
}

export function AccessibleAccordionToggle({
  title,
  panelId,
  isExpanded,
  onToggle,
}: AccordionProps) {
  return (
    <button
      type="button"
      id={`trigger-${panelId}`}
      // ARIA attributes hỗ trợ trợ năng
      aria-expanded={isExpanded}
      aria-controls={panelId}
      onClick={onToggle}
      className="flex w-full items-center justify-between p-4 font-semibold"
    >
      <span>{title}</span>
      <span aria-hidden="true" className={`arrow ${isExpanded ? 'open' : ''}`}>
        ▼
      </span>
    </button>
  );
}

