// Quản lý LocalStorage an toàn có xử lý QuotaExceededError và Type-Safe
export const storageUtil = {
  setItem<T>(key: string, value: T): boolean {
    try {
      const serialized = JSON.stringify(value);
      window.localStorage.setItem(key, serialized);
      return true;
    } catch (error) {
      // Xử lý khi bộ nhớ đầy (QuotaExceededError) hoặc trình duyệt ở chế độ Private Mode bị chặn
      console.error(`Failed to write to localStorage for key: ${key}`, error);
      return false;
    }
  },

  getItem<T>(key: string, fallback: T): T {
    try {
      const item = window.localStorage.getItem(key);
      return item ? (JSON.parse(item) as T) : fallback;
    } catch {
      return fallback;
    }
  },

  removeItem(key: string): void {
    window.localStorage.removeItem(key);
  }
};

export async function handleApiResponse<T>(response: Response): Promise<T> {
  // 204 No Content (thường gặp khi DELETE thành công)
  if (response.status === 204) {
    return {} as T;
  }

  // 304 Not Modified: Browser tự động sử dụng cache hợp lệ từ đĩa
  if (response.status === 304) {
    console.info('Asset served from HTTP Browser Cache.');
  }

  if (!response.ok) {
    switch (response.status) {
      case 401:
        throw new Error('AUTH_UNAUTHORIZED: Token hết hạn, cần silent refresh.');
      case 403:
        throw new Error('AUTH_FORBIDDEN: Bạn không có quyền truy cập tài nguyên này.');
      case 429:
        throw new Error('RATE_LIMITED: Quá nhiều request, vui lòng chờ.');
      case 500:
      case 502:
      case 503:
        throw new Error('SERVER_ERROR: Hệ thống backend đang bảo trì hoặc gặp sự cố.');
      default:
        throw new Error(`HTTP_ERROR: Mã lỗi ${response.status}`);
    }
  }

  return response.json() as Promise<T>;
}

/**
 * MA TRẬN SO SÁNH KIẾN TRÚC TRONG THỰC TẾ SẢN XUẤT:
 *
 * Tiêu chí          | SPA (React, Vue, Vite)    | MPA / Hybrid (Next.js, Astro)
 * -------------------|---------------------------|----------------------------------
 * Initial Load (FCP) | Chậm (đợi tải JS bundle)   | Rất nhanh (HTML render sẵn)
 * Client Transitions | 0ms flicker, cực mượt     | Reload trang (hoặc Soft Navigation)
 * State Preservation | Dễ dàng giữ state qua URL | Mất state nếu không lưu cookie/storage
 * SEO Readiness      | Cần render service / SSR  | Tối ưu SEO mặc định
 * Phù hợp nhất       | SaaS, Dashboard, CRM      | E-commerce, Báo điện tử, Blog, Landing
 */

