// Ứng dụng Closure thực tế: Tạo hàm Memoize Generic an toàn cho Production
export function memoize<TArgs extends unknown[], TReturn>(
  fn: (...args: TArgs) => TReturn
): (...args: TArgs) => TReturn {
  // `cache` nằm trong Lexical Environment của hàm memoize
  // Hàm con bên trong giữ tham chiếu vĩnh viễn tới biến này qua Closure
  const cache = new Map<string, TReturn>();

  return function (...args: TArgs): TReturn {
    const cacheKey = JSON.stringify(args);

    if (cache.has(cacheKey)) {
      return cache.get(cacheKey)!; // Trả về kết quả đã cache tức thì O(1)
    }

    const result = fn(...args);
    cache.set(cacheKey, result);
    return result;
  };
}

// Kiểm chứng Closure:
const heavyCalc = (n: number) => { console.log('Tính toán nặng...'); return n * 2; };
const memoizedCalc = memoize(heavyCalc);
memoizedCalc(5); // In: 'Tính toán nặng...' -> 10
memoizedCalc(5); // Lấy thẳng từ Closure cache, không in log!

