interface UserData { id: string; name: string; }
interface OrderData { orderId: string; total: number; }

// ANTI-PATTERN: Callback Hell (Khó bắt lỗi, lồng nhau sâu)
// getUser(id, (err, user) => {
//   if (err) return;
//   getOrders(user.id, (err, orders) => { ... });
