// PRODUCTION BEST PRACTICE: Async/Await với Error Boundary rõ ràng
export async function fetchUserDashboard(userId: string): Promise<{
  user: UserData;
  orders: OrderData[];
}> {
  try {
    // Tận dụng Promise song song thay vì await tuần tự gây nghẽn (Waterfall)
    const [userRes, ordersRes] = await Promise.all([
      fetch(`/api/users/${userId}`),
      fetch(`/api/users/${userId}/orders`)
    ]);

    if (!userRes.ok || !ordersRes.ok) {
      throw new Error('Không thể tải thông tin Dashboard');
    }

    const user = (await userRes.json()) as UserData;
    const orders = (await ordersRes.json()) as OrderData[];

    return { user, orders };
  } catch (error) {
    console.error('[Dashboard Error]:', error);
    throw error; // Re-throw để UI layer hiển thị Error Toast
  }
}

// 1. DEBOUNCE: Chỉ thực thi sau khi khoảng lặng tĩnh đủ 'delay' ms
export function debounce<T extends (...args: unknown[]) => void>(
  fn: T,
  delay: number
): (...args: Parameters<T>) => void {
  let timer: NodeJS.Timeout | null = null;

  return function (...args: Parameters<T>) {
    if (timer) clearTimeout(timer);
    timer = setTimeout(() => {
      fn(...args);
      timer = null;
    }, delay);
  };
}

// 2. THROTTLE: Đảm bảo tần suất thực thi tối đa 1 lần mỗi 'limit' ms
export function throttle<T extends (...args: unknown[]) => void>(
  fn: T,
  limit: number
): (...args: Parameters<T>) => void {
  let inThrottle = false;

  return function (...args: Parameters<T>) {
    if (!inThrottle) {
      fn(...args);
      inThrottle = true;
      setTimeout(() => {
        inThrottle = false;
      }, limit);
    }
  };
}

