interface ApiResponse {
  settings?: {
    retryCount?: number; // Có thể là 0
    enableNotification?: boolean; // Có thể là false
  };
  getUserDisplayName?: () => string;
}

function processConfig(response?: ApiResponse) {
  // 1. Optional Chaining với thuộc tính lồng nhau và gọi hàm an toàn
  const userName = response?.getUserDisplayName?.() ?? 'Ẩn danh';

  // 2. Cạm bẫy của toán tử Logical OR (||)
  const retryCountWithOR = response?.settings?.retryCount || 3; 
  // Nếu retryCount = 0 -> retryCountWithOR = 3 (SAI NGHIỆP VỤ!)

  // 3. Giải pháp chuẩn xác với Nullish Coalescing (??)
  const retryCount = response?.settings?.retryCount ?? 3;
  // Nếu retryCount = 0 -> retryCount = 0 (CHÍNH XÁC)

  const isNotifEnabled = response?.settings?.enableNotification ?? true;
  // Nếu enableNotification = false -> giữ nguyên false chứ không bị ép thành true

  return { userName, retryCount, isNotifEnabled };
}

