// 2. WEAKMAP: Lưu trữ metadata liên kết với DOM Node chống Memory Leak
const domClickTracker = new WeakMap<HTMLElement, { clickCount: number }>();

export function attachTracker(element: HTMLElement): void {
  domClickTracker.set(element, { clickCount: 0 });

  element.addEventListener('click', () => {
    const data = domClickTracker.get(element);
    if (data) data.clickCount++;
  });
  // Khi element bị removeChild khỏi DOM và không còn tham chiếu nào khác,
  // WeakMap sẽ tự động giải phóng dữ liệu trong GC mà không cần dọn dẹp thủ công!
}

// 1. PROMISE.ALLSETTLED: Tải Dashboard chịu lỗi từng phần (Graceful Degradation)
interface DashboardData {
  profile: unknown;
  notifications: unknown[];
}

export async function loadResilientDashboard(): Promise<DashboardData> {
  const [profileResult, notifsResult] = await Promise.allSettled([
    fetch('/api/profile').then(r => r.json()),
    fetch('/api/notifications').then(r => r.json())
  ]);

  return {
    profile: profileResult.status === 'fulfilled' ? profileResult.value : null,
    notifications: notifsResult.status === 'fulfilled' ? notifsResult.value : []
  };
}

// 2. PROMISE.RACE: Tạo timeout cho Request mạng
export function fetchWithTimeout<T>(url: string, timeoutMs: number = 5000): Promise<T> {
  const timeoutPromise = new Promise<never>((_, reject) => {
    setTimeout(() => reject(new Error(`Request timeout after ${timeoutMs}ms`)), timeoutMs);
  });

  return Promise.race([
    fetch(url).then(res => res.json() as Promise<T>),
    timeoutPromise
  ]);
}

