// 1. SỬ DỤNG WEB WORKER: Giải phóng Main Thread khỏi thuật toán nặng
const imageWorker = new Worker(new URL('./image-compressor.worker.ts', import.meta.url), {
  type: 'module'
});

export function compressLargeImage(buffer: ArrayBuffer): Promise<ArrayBuffer> {
  return new Promise((resolve) => {
    imageWorker.onmessage = (event: MessageEvent<{ compressedBuffer: ArrayBuffer }>) => {
      resolve(event.data.compressedBuffer);
    };

    // Zero-copy transfer: chuyển quyền sở hữu buffer, main thread mất quyền sở hữu nhưng 0ms latency
    imageWorker.postMessage({ buffer }, [buffer]);
  });
}

