// Hệ thống Lazy Loading hình ảnh chuyên nghiệp bằng IntersectionObserver
export function setupImageLazyLoading(): () => void {
  const observer = new IntersectionObserver(
    (entries, obs) => {
      entries.forEach((entry) => {
        if (entry.isIntersecting) {
          const img = entry.target as HTMLImageElement;
          const realSrc = img.dataset.src;
          if (realSrc) {
            img.src = realSrc;
            img.removeAttribute('data-src');
          }
          // Ngừng theo dõi phần tử đã tải xong để tiết kiệm tài nguyên
          obs.unobserve(img);
        }
      });
    },
    {
      root: null, // Mặc định là Viewport của trình duyệt
      rootMargin: '150px', // Tải trước khi người dùng cuộn tới 150px
      threshold: 0.01 // Bắt đầu load ngay khi 1% mép ảnh vừa chạm ngưỡng
    }
  );

  document.querySelectorAll<HTMLImageElement>('img[data-src]').forEach((img) => {
    observer.observe(img);
  });

  // Trả về hàm cleanup khi unmount component
  return () => observer.disconnect();
}

