// ANTIPATTERN: LAYOUT THRASHING (Gây giật lag 10fps vì ép Reflow liên tục)
export function badResizeElements(elements: HTMLElement[]) {
  elements.forEach((el) => {
    // ĐỌC (Ép Forced Reflow)
    const currentWidth = el.offsetWidth;
    // GHI (Làm bẩn Layout)
    el.style.width = `${currentWidth + 10}px`;
  });
}

// BEST PRACTICE: Gom nhóm thao tác Đọc trước, Ghi sau (Batching)
export function optimizedResizeElements(elements: HTMLElement[]) {
  // Bước 1: Đọc toàn bộ kích thước trong 1 lần duy nhất
  const widths = elements.map((el) => el.offsetWidth);

  // Bước 2: Ghi toàn bộ thay đổi cùng lúc (Trình duyệt chỉ cần 1 lần Reflow duy nhất)
  requestAnimationFrame(() => {
    elements.forEach((el, index) => {
      el.style.width = `${widths[index] + 10}px`;
    });
  });
}

/**
 * MINH HỌA TIMELINE TỪ PERFORMANCE API TRONG TRÌNH DUYỆT (Navigation Timing Level 2)
 */
export function inspectPageLoadTimeline() {
  const navTiming = performance.getEntriesByType('navigation')[0] as PerformanceNavigationTiming;

  if (!navTiming) return;

  console.table({
    '1. DNS Lookup': `${(navTiming.domainLookupEnd - navTiming.domainLookupStart).toFixed(2)} ms`,
    '2. TCP Handshake': `${(navTiming.connectEnd - navTiming.connectStart).toFixed(2)} ms`,
    '3. TLS Negotiation': `${(navTiming.connectEnd - navTiming.secureConnectionStart).toFixed(2)} ms`,
    '4. TTFB (Time to First Byte)': `${(navTiming.responseStart - navTiming.requestStart).toFixed(2)} ms`,
    '5. HTML Download': `${(navTiming.responseEnd - navTiming.responseStart).toFixed(2)} ms`,
    '6. DOM Interactive (Parsing)': `${(navTiming.domInteractive - navTiming.responseEnd).toFixed(2)} ms`,
    '7. DOM Complete': `${(navTiming.domComplete - navTiming.domInteractive).toFixed(2)} ms`,
    '8. Full Load Event': `${(navTiming.loadEventEnd - navTiming.loadEventStart).toFixed(2)} ms`,
  });
}

