import { useState, useEffect, useRef } from 'react';

export function useDebouncedSearch(query: string, delayMs: number = 300) {
  const [results, setResults] = useState<string[]>([]);
  const [isLoading, setIsLoading] = useState(false);
  const abortControllerRef = useRef<AbortController | null>(null);

  useEffect(() => {
    if (!query.trim()) {
      setResults([]);
      return;
    }

    // 1. Thiết lập Debounce Timer
    const timerId = setTimeout(async () => {
      // 2. Hủy bỏ request đang chạy dở trước đó nếu có
      if (abortControllerRef.current) {
        abortControllerRef.current.abort();
      }

      const controller = new AbortController();
      abortControllerRef.current = controller;
      setIsLoading(true);

      try {
        const res = await fetch(`/api/search?q=${encodeURIComponent(query)}`, {
          signal: controller.signal
        });
        if (!res.ok) throw new Error('Search failed');
        const data = await res.json();
        setResults(data.items);
      } catch (error: unknown) {
        if ((error as DOMException)?.name !== 'AbortError') {
          console.error('Lỗi tìm kiếm:', error);
        }
      } finally {
        setIsLoading(false);
      }
    }, delayMs);

    // Cleanup khi query thay đổi hoặc component unmount
    return () => {
      clearTimeout(timerId);
      if (abortControllerRef.current) {
        abortControllerRef.current.abort();
      }
    };
  }, [query, delayMs]);

  return { results, isLoading };
}

interface RetryOptions {
  maxRetries?: number;
  baseDelayMs?: number;
  maxDelayMs?: number;
}

export async function fetchWithExponentialBackoff<T>(
  url: string,
  options: RequestInit = {},
  retryOpts: RetryOptions = {}
): Promise<T> {
  const { maxRetries = 3, baseDelayMs = 500, maxDelayMs = 5000 } = retryOpts;

  for (let attempt = 0; attempt <= maxRetries; attempt++) {
    try {
      const response = await fetch(url, options);

      // Thành công
      if (response.ok) return (await response.json()) as T;

      // Lỗi 4xx (trừ 429 Too Many Requests) là Permanent Error -> DỪNG NGAY, KHÔNG RETRY!
      if (response.status >= 400 && response.status < 500 && response.status !== 429) {
        throw new Error(`Client Error (${response.status}): Không được retry.`);
      }

      // Nếu là lần thử cuối cùng thì ném lỗi
      if (attempt === maxRetries) {
        throw new Error(`Request thất bại sau ${maxRetries} lần thử lại. Status: ${response.status}`);
      }
    } catch (err: unknown) {
      if (attempt === maxRetries) throw err;
    }

    // Tính toán độ trễ theo Exponential Backoff kết hợp Full Jitter
    const exponentialDelay = Math.min(maxDelayMs, baseDelayMs * Math.pow(2, attempt));
    const jitteredDelay = Math.random() * exponentialDelay;

    console.warn(`Lần thử ${attempt + 1} thất bại. Đang chờ ${jitteredDelay.toFixed(0)}ms trước khi thử lại...`);
    await new Promise((res) => setTimeout(res, jitteredDelay));
  }

  throw new Error('Unreachable code');
}

export interface UploadProgressPayload {
  loaded: number;
  total: number;
  percent: number;
}

// Upload File có báo cáo tiến độ % và khả năng hủy bỏ
export function uploadFileWithProgress(
  file: File,
  uploadUrl: string,
  onProgress: (progress: UploadProgressPayload) => void
): { promise: Promise<unknown>; cancel: () => void } {
  const xhr = new XMLHttpRequest();

  const promise = new Promise((resolve, reject) => {
    xhr.upload.addEventListener('progress', (event) => {
      if (event.lengthComputable) {
        const percent = Math.round((event.loaded / event.total) * 100);
        onProgress({ loaded: event.loaded, total: event.total, percent });
      }
    });

    xhr.addEventListener('load', () => {
      if (xhr.status >= 200 && xhr.status < 300) {
        resolve(JSON.parse(xhr.responseText || '{}'));
      } else {
        reject(new Error(`Upload failed with status: ${xhr.status}`));
      }
    });

    xhr.addEventListener('error', () => reject(new Error('Network error during upload')));
    xhr.addEventListener('abort', () => reject(new Error('Upload cancelled by user')));

    const formData = new FormData();
    formData.append('file', file);

    xhr.open('POST', uploadUrl);
    xhr.send(formData);
  });

  return {
    promise,
    cancel: () => xhr.abort()
  };
}

