// 1. UNKNOWN: Bắt buộc Type Narrowing trước khi sử dụng
export function parseApiResponse(rawPayload: unknown): string {
  if (typeof rawPayload === 'string') {
    return rawPayload.toUpperCase(); // Hợp lệ sau khi đã kiểm tra
  }
  if (rawPayload && typeof rawPayload === 'object' && 'message' in rawPayload) {
    return String((rawPayload as { message: unknown }).message);
  }
  throw new Error('Dữ liệu không đúng định dạng mong đợi');
}

