// Props: Định nghĩa hợp đồng dữ liệu từ cha truyền xuống (Read-Only)
interface CounterCardProps {
  title: string;
  initialCount?: number;
  onCountReachedMax?: (currentCount: number) => void;
}

export const CounterCard: React.FC<CounterCardProps> = ({
  title,
  initialCount = 0,
  onCountReachedMax
}) => {
  // State: Dữ liệu nội bộ tự quản lý, kích hoạt re-render khi thay đổi
  const [count, setCount] = useState<number>(initialCount);

  const handleIncrement = () => {
    const nextCount = count + 1;
    setCount(nextCount);

    if (nextCount >= 10 && onCountReachedMax) {
      // Giao tiếp ngược lên cha thông qua callback prop
      onCountReachedMax(nextCount);
    }
  };

  return (
    <div className="rounded-lg border p-4 shadow-sm">
      <h3 className="text-lg font-bold">{title}</h3>
      <p className="text-2xl font-semibold">Số lượng: {count}</p>
      <button
        onClick={handleIncrement}
        className="mt-2 rounded bg-blue-600 px-4 py-2 text-white hover:bg-blue-700"
      >
        Tăng số
      </button>
    </div>
  );
};

