import React, { useState } from 'react';

interface TodoItem {
  id: string; // Khóa định danh duy nhất ổn định từ DB hoặc crypto.randomUUID()
  text: string;
}

export function TodoList() {
  const [todos, setTodos] = useState<TodoItem[]>([
    { id: 'todo-1', text: 'Học React Fiber' },
    { id: 'todo-2', text: 'Tối ưu Web Vitals' },
  ]);

  const removeFirst = () => {
    setTodos((prev) => prev.slice(1));
  };

  return (
