        Xóa mục đầu tiên
      </button>
      <ul>
        {todos.map((todo) => (
          // BEST PRACTICE: Dùng id duy nhất ổn định làm key
          // ANTI-PATTERN: key={index} sẽ gây lỗi giữ sai state của ô input con!
          <li key={todo.id} className="flex items-center gap-2 py-1">
            <input type="text" defaultValue={todo.text} className="border px-2" />
          </li>
        ))}
      </ul>
