import { useState, useEffect } from 'react';

export function AccurateTimer() {
  const [seconds, setSeconds] = useState(0);

  useEffect(() => {
    // ANTI-PATTERN GÂY STALE CLOSURE:
    // const id = setInterval(() => setSeconds(seconds + 1), 1000); // seconds luôn là 0!

    // BEST PRACTICE: Dùng Functional State Update để luôn đọc state mới nhất
    const intervalId = setInterval(() => {
      setSeconds((prevSeconds) => prevSeconds + 1);
    }, 1000);

    // Bắt buộc dọn dẹp timer khi unmount
    return () => clearInterval(intervalId);
  }, []); // Dependency array rỗng an toàn vì functional update không phụ thuộc closure state

  return <div>Đã trôi qua: {seconds} giây</div>;
}

import React, { useRef, useState } from 'react';

// 1. CONTROLLED: Phù hợp khi cần format hoặc validate tức thì thời gian thực
export function ControlledInput() {
  const [creditCard, setCreditCard] = useState('');

  const handleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    // Tự động format thêm dấu gạch nối
    const formatted = e.target.value.replace(/\D/g, '').slice(0, 16);
    setCreditCard(formatted);
  };

  return <input value={creditCard} onChange={handleChange} placeholder="Số thẻ" />;
}

// 2. UNCONTROLLED: Tối ưu hiệu năng form lớn, không re-render khi gõ phím
export function UncontrolledForm() {
  const formRef = useRef<HTMLFormElement>(null);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!formRef.current) return;
    const data = new FormData(formRef.current);
    console.log('Submitted Payload:', Object.fromEntries(data.entries()));
  };

  return (
    <form ref={formRef} onSubmit={handleSubmit}>
      <input name="fullName" defaultValue="Nguyễn Văn A" />
      <input name="email" type="email" defaultValue="a@gmail.com" />
      <button type="submit">Gửi dữ liệu</button>
    </form>
  );
}

import React, { useRef, useState, useEffect } from 'react';

export function FocusableTimer() {
  const [count, setCount] = useState(0);
  // 1. Ref để truy cập DOM Element an toàn
  const inputRef = useRef<HTMLInputElement>(null);
  // 2. Ref để lưu biến ngầm không gây re-render (Timer ID)
  const timerRef = useRef<NodeJS.Timeout | null>(null);

  useEffect(() => {
    // Tự động focus ô input khi mở màn hình
    inputRef.current?.focus();

    timerRef.current = setInterval(() => {
      setCount((c) => c + 1);
    }, 1000);

    return () => {
      if (timerRef.current) clearInterval(timerRef.current);
    };
  }, []);

  return (
    <div>
      <input ref={inputRef} placeholder="Tự động focus tại đây" className="border p-2" />
      <p>Số đếm: {count}</p>
      <button onClick={() => timerRef.current && clearInterval(timerRef.current)}>
        Dừng Timer
      </button>
    </div>
  );
}

import React, { useReducer } from 'react';

interface CartState {
  items: { id: string; price: number; qty: number }[];
  discountPercent: number;
}

type CartAction =
  | { type: 'ADD_ITEM'; item: { id: string; price: number } }
  | { type: 'REMOVE_ITEM'; id: string }
  | { type: 'APPLY_DISCOUNT'; percent: number };

// Pure Reducer Function: Dễ dàng Unit Test độc lập không cần mount React DOM
function cartReducer(state: CartState, action: CartAction): CartState {
  switch (action.type) {
    case 'ADD_ITEM': {
      const existing = state.items.find((i) => i.id === action.item.id);
      const items = existing
        ? state.items.map((i) => (i.id === action.item.id ? { ...i, qty: i.qty + 1 } : i))
        : [...state.items, { ...action.item, qty: 1 }];
      return { ...state, items };
    }
    case 'REMOVE_ITEM':
      return { ...state, items: state.items.filter((i) => i.id !== action.id) };
    case 'APPLY_DISCOUNT':
      return { ...state, discountPercent: Math.min(100, Math.max(0, action.percent)) };
    default:
      return state;
  }
}

export function ShoppingCart() {
  const [state, dispatch] = useReducer(cartReducer, { items: [], discountPercent: 0 });

  return (
    <div>
      <h3>Số mặt hàng: {state.items.length}</h3>
      <button onClick={() => dispatch({ type: 'ADD_ITEM', item: { id: 'p1', price: 100 } })}>
        Thêm sản phẩm
      </button>
    </div>
  );
}

import React, { createContext, useContext, useState, PropsWithChildren } from 'react';

// 1. NGỮ CẢNH HOÀN HẢO CHO CONTEXT API: Dữ liệu tần suất đổi thấp (Theme)
type Theme = 'light' | 'dark';
interface ThemeContextType {
  theme: Theme;
  toggleTheme: () => void;
}

const ThemeContext = createContext<ThemeContextType | null>(null);

export function ThemeProvider({ children }: PropsWithChildren) {
  const [theme, setTheme] = useState<Theme>('light');
  const toggleTheme = () => setTheme((t) => (t === 'light' ? 'dark' : 'light'));

  return (
    <ThemeContext.Provider value={{ theme, toggleTheme }}>
      {children}
    </ThemeContext.Provider>
  );
}

// Custom Hook chuẩn an toàn, cảnh báo nếu dùng ngoài Provider
export function useTheme(): ThemeContextType {
  const ctx = useContext(ThemeContext);
  if (!ctx) throw new Error('useTheme phải được sử dụng bên trong ThemeProvider');
  return ctx;
}

import { createSlice, createAsyncThunk, configureStore, PayloadAction } from '@reduxjs/toolkit';

// 1. Thunk Middleware: Xử lý Side-Effect bất đồng bộ gọi API
export const fetchUserProfile = createAsyncThunk(
  'user/fetchProfile',
  async (userId: string) => {
    const res = await fetch(`/api/users/${userId}`);
    return (await res.json()) as { id: string; name: string };
  }
);

// 2. Slice kết hợp Actions và Reducer chuẩn Redux Toolkit
const userSlice = createSlice({
  name: 'user',
  initialState: { data: null as { id: string; name: string } | null, loading: false },
  reducers: {
    clearUser: (state) => {
      state.data = null; // Immer tự động biến đổi thành bản sao bất biến an toàn
    }
  },
  extraReducers: (builder) => {
    builder
      .addCase(fetchUserProfile.pending, (state) => { state.loading = true; })
      .addCase(fetchUserProfile.fulfilled, (state, action) => {
        state.loading = false;
        state.data = action.payload;
      });
  }
});

// 3. Configure Store với Middleware tích hợp sẵn
export const store = configureStore({
  reducer: { user: userSlice.reducer }
});

import React, { useState, useMemo, useCallback } from 'react';

// 1. React.memo: Chỉ re-render khi props thay đổi thật sự
const ExpensiveItemRow = React.memo(({ title, onDelete }: { title: string; onDelete: (id: string) => void }) => {
  console.log(`Render dòng: ${title}`);
  return <button onClick={() => onDelete(title)}>Xóa {title}</button>;
});

export function ProductManager() {
  const [items, setItems] = useState(['Laptop', 'Phone', 'Tablet']);
  const [count, setCount] = useState(0);

  // 2. useMemo: Cache kết quả lọc dữ liệu phức tạp
  const filteredItems = useMemo(() => {
    return items.filter((item) => item.toLowerCase().includes('a'));
  }, [items]);

  // 3. useCallback: Ổn định tham chiếu hàm để React.memo của con phát huy tác dụng
  const handleDelete = useCallback((itemToDelete: string) => {
    setItems((prev) => prev.filter((i) => i !== itemToDelete));
  }, []); // Không phụ thuộc items vì dùng functional update

  return (
    <div>
      <button onClick={() => setCount((c) => c + 1)}>Tăng count độc lập: {count}</button>
      {filteredItems.map((item) => (
        <ExpensiveItemRow key={item} title={item} onDelete={handleDelete} />
      ))}
    </div>
  );
}

