import React, { Component, ErrorInfo, ReactNode } from 'react';

interface Props {
  children: ReactNode;
  fallback?: ReactNode;
}

interface State {
  hasError: boolean;
  error: Error | null;
}

export class GlobalErrorBoundary extends Component<Props, State> {
  public state: State = {
    hasError: false,
    error: null
  };

  // Cập nhật state để render Fallback UI trong lần render tiếp theo
  public static getDerivedStateFromError(error: Error): State {
    return { hasError: true, error };
  }

  // Ghi log lỗi lên dịch vụ giám sát (Sentry, Datadog)
  public componentDidCatch(error: Error, errorInfo: ErrorInfo) {
    console.error('[Telemetry] Uncaught error caught by Boundary:', error, errorInfo.componentStack);
  }

  public render() {
    if (this.state.hasError) {
      return (
        this.props.fallback || (
          <div className="p-4 border border-red-300 bg-red-50 text-red-700 rounded">
            <h3>Đã xảy ra sự cố tại khu vực này.</h3>
            <button onClick={() => this.setState({ hasError: false, error: null })}>
              Thử tải lại
            </button>
          </div>
        )
      );
    }
    return this.props.children;
  }
}

import React from 'react';

interface AsyncBoundaryProps<T> {
  isLoading: boolean;
  error: Error | null;
  data: T[] | null | undefined;
  onRetry: () => void;
  renderItem: (item: T) => React.ReactNode;
  emptyMessage?: string;
}

export function AsyncListView<T>({
  isLoading,
  error,
  data,
  onRetry,
  renderItem,
  emptyMessage = 'Không có dữ liệu nào.'
}: AsyncBoundaryProps<T>) {
  // 1. Trạng thái Loading: Hiển thị Skeleton Screen
  if (isLoading) {
    return (
      <div className="space-y-2 animate-pulse">
        <div className="h-10 bg-gray-200 rounded" />
        <div className="h-10 bg-gray-200 rounded" />
      </div>
    );
  }

  // 2. Trạng thái Error: Có nút Retry rõ ràng
  if (error) {
    return (
      <div className="p-4 text-center text-red-600 border border-red-200 rounded">
        <p>Lỗi: {error.message}</p>
        <button onClick={onRetry} className="mt-2 px-3 py-1 bg-red-600 text-white rounded">
          Thử lại
        </button>
      </div>
    );
  }

  // 3. Trạng thái Empty: Call to Action
  if (!data || data.length === 0) {
    return (
      <div className="p-8 text-center text-gray-500">
        <p>{emptyMessage}</p>
      </div>
    );
  }

  // 4. Trạng thái Success: Render danh sách
  return <ul>{data.map(renderItem)}</ul>;
}

import { useState, useEffect } from 'react';

// 1. CHIẾN THẮNG TUYỆT ĐỐI CỦA CUSTOM HOOKS: Phẳng, Tự nhiên, Type-Safe 100%
export function useWindowDimensions() {
  const [dimensions, setDimensions] = useState({
    width: typeof window !== 'undefined' ? window.innerWidth : 0,
    height: typeof window !== 'undefined' ? window.innerHeight : 0,
  });

  useEffect(() => {
    const handleResize = () => {
      setDimensions({ width: window.innerWidth, height: window.innerHeight });
    };
    window.addEventListener('resize', handleResize);
    return () => window.removeEventListener('resize', handleResize);
  }, []);

  return dimensions;
}

// Sử dụng cực kỳ gọn gàng bên trong Component:
export function ResponsiveNavbar() {
  const { width } = useWindowDimensions();
  return <nav>{width < 768 ? <MobileMenu /> : <DesktopMenu />}</nav>;
}

import React, { useState, useRef, useLayoutEffect } from 'react';

export function TooltipBubble({ targetRect }: { targetRect: DOMRect }) {
  const tooltipRef = useRef<HTMLDivElement>(null);
  const [topPosition, setTopPosition] = useState(0);

  // DÙNG useLayoutEffect ĐỂ TRÁNH FLICKER:
  // Chạy TRƯỚC KHI trình duyệt vẽ lên màn hình, người dùng không bao giờ thấy vị trí 0 bị nhảy!
  useLayoutEffect(() => {
    if (tooltipRef.current) {
      const tooltipHeight = tooltipRef.current.getBoundingClientRect().height;
      // Định vị tooltip nằm ngay phía trên target button
      setTopPosition(targetRect.top - tooltipHeight - 8);
    }
  }, [targetRect]);

  return (
    <div
      ref={tooltipRef}
      style={{ top: `${topPosition}px`, position: 'fixed' }}
      className="bg-black text-white p-2 rounded shadow-lg"
    >
      Thông tin Tooltip chuẩn xác!
    </div>
  );
}

import React, { useEffect } from 'react';
import { useForm } from 'react-hook-form';
import { zodResolver } from '@hookform/resolvers/zod';
import { z } from 'zod';

// 1. Khai báo Schema Validation bằng Zod
const formSchema = z.object({
  title: z.string().min(5, 'Tiêu đề ít nhất 5 ký tự'),
  content: z.string().min(20, 'Nội dung ít nhất 20 ký tự'),
  category: z.string().nonempty('Vui lòng chọn danh mục'),
});
type FormData = z.infer<typeof formSchema>;

const DRAFT_KEY = 'article_draft_v1';

export function AdvancedDraftForm() {
  const { register, handleSubmit, watch, reset, formState: { errors, isDirty } } = useForm<FormData>({
    resolver: zodResolver(formSchema),
    defaultValues: async () => {
      // Khôi phục bản nháp từ localStorage khi mở trang
      const saved = localStorage.getItem(DRAFT_KEY);
      return saved ? JSON.parse(saved) : { title: '', content: '', category: '' };
    }
  });

  // 2. Debounced Autosave bản nháp sau 1 giây ngừng gõ
  const watchedValues = watch();
  useEffect(() => {
    if (!isDirty) return;
    const timer = setTimeout(() => {
      localStorage.setItem(DRAFT_KEY, JSON.stringify(watchedValues));
      console.info('Đã tự động lưu bản nháp vào LocalStorage.');
    }, 1000);
    return () => clearTimeout(timer);
  }, [watchedValues, isDirty]);

  const onSubmit = async (data: FormData) => {
    console.log('Gửi dữ liệu chính thức:', data);
    localStorage.removeItem(DRAFT_KEY); // Xóa bản nháp sau khi submit thành công
    reset(data);
  };

  return (
    <form onSubmit={handleSubmit(onSubmit)} className="space-y-4 max-w-lg">
      <div>
        <input {...register('title')} placeholder="Tiêu đề" className="border p-2 w-full" />
        {errors.title && <p className="text-red-500 text-sm">{errors.title.message}</p>}
      </div>
      <button type="submit" className="bg-blue-600 text-white px-4 py-2 rounded">
        Xuất bản bài viết
      </button>
    </form>
  );
}

import React, { useRef } from 'react';
import { useVirtualizer } from '@tanstack/react-virtual';

// DANH SÁCH 50,000 ITEMS SIÊU NHẸ NHỜ DOM VIRTUALIZATION
export function VirtualizedInfiniteList({ items }: { items: string[] }) {
  const parentRef = useRef<HTMLDivElement>(null);

  const rowVirtualizer = useVirtualizer({
    count: items.length,
    getScrollElement: () => parentRef.current,
    estimateSize: () => 50, // Chiều cao ước tính mỗi dòng 50px
    overscan: 5, // Render thêm 5 item dự phòng ngoài màn hình để cuộn mượt mà
  });

  return (
    <div
      ref={parentRef}
      className="h-[400px] overflow-auto border border-gray-300 rounded"
    >
      {/* Container ảo giữ nguyên tổng chiều cao thật của 50,000 items */}
      <div
        style={{
          height: `${rowVirtualizer.getTotalSize()}px`,
          width: '100%',
          position: 'relative',
        }}
      >
        {/* CHỈ CÓ ~10 DOM NODES ĐƯỢC RENDER THỰC SỰ TRÊN MÀN HÌNH */}
        {rowVirtualizer.getVirtualItems().map((virtualRow) => (
          <div
            key={virtualRow.index}
            style={{
              position: 'absolute',
              top: 0,
              left: 0,
              width: '100%',
              height: `${virtualRow.size}px`,
              transform: `translateY(${virtualRow.start}px)`,
            }}
            className="p-3 border-b flex items-center bg-white"
          >
            {items[virtualRow.index]}
          </div>
        ))}
      </div>
    </div>
  );
}

import { useQuery, useQueryClient } from '@tanstack/react-query';

interface UserProfile {
  id: string;
  name: string;
}

export function useUserProfile(userId: string) {
  return useQuery({
    queryKey: ['user', userId],
    queryFn: async () => {
      const res = await fetch(`/api/users/${userId}`);
      if (!res.ok) throw new Error('Không thể tải profile');
      return (await res.json()) as UserProfile;
    },
    // Dữ liệu được coi là fresh trong 5 phút -> Không bao giờ gọi lại API thừa thãi
    staleTime: 5 * 60 * 1000,
    // Giữ cache trong RAM 30 phút sau khi component unmount
    gcTime: 30 * 60 * 1000,
    // Không refetch lại khi focus cửa sổ nếu dữ liệu vẫn đang trong staleTime
    refetchOnWindowFocus: true,
  });
}

// Chủ động làm mới cache (Invalidation) sau khi sửa đổi dữ liệu (Mutation)
export function useUpdateUser() {
  const queryClient = useQueryClient();
  return async (userId: string, newName: string) => {
    await fetch(`/api/users/${userId}`, { method: 'PATCH', body: JSON.stringify({ name: newName }) });
    // Đánh dấu stale để tự động kéo dữ liệu mới nhất về
    queryClient.invalidateQueries({ queryKey: ['user', userId] });
  };
}

