import { useMutation, useQueryClient } from '@tanstack/react-query';

interface Post { id: string; likesCount: number; isLiked: boolean; }

export function useLikePostMutation(postId: string) {
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: async (shouldLike: boolean) => {
      const res = await fetch(`/api/posts/${postId}/like`, {
        method: 'POST',
        body: JSON.stringify({ isLiked: shouldLike }),
      });
      if (!res.ok) throw new Error('Không thể thích bài viết');
      return res.json();
    },
    // BƯỚC 1: CẬP NHẬT GIAO DIỆN LẠC QUAN NGAY LẬP TỨC 0MS
    onMutate: async (shouldLike: boolean) => {
      await queryClient.cancelQueries({ queryKey: ['post', postId] });
      const previousPost = queryClient.getQueryData<Post>(['post', postId]);

      if (previousPost) {
        queryClient.setQueryData<Post>(['post', postId], {
          ...previousPost,
          isLiked: shouldLike,
          likesCount: previousPost.likesCount + (shouldLike ? 1 : -1),
        });
      }
      return { previousPost }; // Trả về snapshot để phục vụ rollback
    },
    // BƯỚC 2: ROLLBACK NẾU GẶP LỖI MẠNG HOẶC SERVER 500
    onError: (err, variables, context) => {
      if (context?.previousPost) {
        queryClient.setQueryData(['post', postId], context.previousPost);
      }
      alert('Lỗi: ' + err.message);
    },
    // BƯỚC 3: LUÔN ĐỒNG BỘ LẠI VỚI SERVER KHI XONG
    onSettled: () => {
      queryClient.invalidateQueries({ queryKey: ['post', postId] });
    },
  });
}

import React from 'react';
import { Navigate, useLocation } from 'react-router-dom';

type AuthStatus = 'loading' | 'authenticated' | 'unauthenticated';

interface AuthContextType {
  status: AuthStatus;
  user: { id: string; email: string } | null;
}

// Giả lập hook useAuth
const useAuth = (): AuthContextType => ({ status: 'loading', user: null });

export function ProtectedRoute({ children }: { children: React.ReactNode }) {
  const { status } = useAuth();
  const location = useLocation();

  // 1. Chặn hoàn toàn Content Flash khi đang kiểm tra token
  if (status === 'loading') {
    return (
      <div className="flex h-screen items-center justify-center bg-gray-50">
        <div className="h-8 w-8 animate-spin rounded-full border-4 border-blue-600 border-t-transparent" />
      </div>
    );
  }

  // 2. Chuyển hướng an toàn kèm theo URL gốc để quay lại sau khi login
  if (status === 'unauthenticated') {
    return <Navigate to={`/login?returnUrl=${encodeURIComponent(location.pathname)}`} replace />;
  }

  // 3. Chỉ render nội dung bảo mật khi đã xác thực 100%
  return <>{children}</>;
}

