// Hàm TypeScript mô phỏng kiểm tra ETag trong tầng Server API:
export function handleConditionalGet(reqETag: string | null, currentETag: string) {
  if (reqETag === currentETag) {
    return { status: 304, message: 'Not Modified (Sử dụng cache trình duyệt)' };
  }
  return { status: 200, message: 'Gửi toàn bộ nội dung mới' };
}

import React, { useState } from 'react';

export function DocumentManager() {
  const [isExporting, setIsExporting] = useState(false);

  // DYNAMIC IMPORT THEO YÊU CẦU: jspdf (300KB) CHỈ TẢI KHI CLICK
  const handleExportPdf = async () => {
    setIsExporting(true);
    try {
      const { jsPDF } = await import('jspdf'); // Dynamic import tạo chunk riêng
      const doc = new jsPDF();
      doc.text('Báo cáo doanh thu', 10, 10);
      doc.save('report.pdf');
    } catch (err) {
      console.error('Không thể tải thư viện xuất PDF:', err);
    } finally {
      setIsExporting(false);
    }
  };

  return (
    <button onClick={handleExportPdf} disabled={isExporting}>
      {isExporting ? 'Đang chuẩn bị PDF...' : 'Xuất file PDF'}
    </button>
  );
}

