// 2. Tối ưu hóa INP: Bẻ nhỏ Long Task bằng scheduler.yield() hiện đại
export async function processHugeListOptimized(items: string[]) {
  for (let i = 0; i < items.length; i++) {
    // Thực thi xử lý item...
    if (i % 100 === 0) {
      // Nhường quyền Main Thread để trình duyệt vẽ UI và nhận tương tác click của người dùng!
      if ('scheduler' in window && 'yield' in (window as unknown as { scheduler: { yield: () => Promise<void> } }).scheduler) {
        await (window as unknown as { scheduler: { yield: () => Promise<void> } }).scheduler.yield();
      } else {
        await new Promise((res) => setTimeout(res, 0));
      }
    }
  }
}

