import { execSync } from 'node:child_process';

/**
 * Quy trình sửa commit nhầm (quên file hoặc sai message) bằng Git CLI:
 *
 * 1. Thêm file bị bỏ sót vào Staging Area:
 *    git add src/features/auth/styles/login.css
 *
 * 2. Gộp vào commit gần nhất (giữ nguyên message cũ):
 *    git commit --amend --no-edit
 *
 * 3. Hoặc vừa gộp vừa sửa lại commit message chuẩn Conventional Commits:
 *    git commit --amend -m "feat(auth): implement login modal with responsive styles"
 */

// Minh họa hàm tiện ích tự động hóa trong CI/CD hoặc Git hooks:
export function safeAmendCommit(stagedFiles: string[], message?: string): void {
  stagedFiles.forEach((file) => execSync(`git add "${file}"`));
  const cmd = message
    ? `git commit --amend -m "${message}"`
    : 'git commit --amend --no-edit';
  execSync(cmd, { stdio: 'inherit' });
}

import { execSync } from 'node:child_process';

/**
 * SO SÁNH QUY TRÌNH MERGE VS REBASE TRONG DỰ ÁN FRONTEND TEAM:
 *
 * 1. Đồng bộ code mới nhất từ main vào feature branch (Rebase để giữ linear log):
 *    git checkout feature/user-profile
 *    git fetch origin
 *    git rebase origin/main
 *
 * 2. Tích hợp feature branch vào main sau khi review Pull Request (Merge để lưu vết mốc):
 *    git checkout main
 *    git merge --no-ff feature/user-profile -m "merge: complete user profile feature"
 */

// GOLDEN RULE OF REBASING: Tuyệt đối không rebase các commit đã push lên public branch!
export function syncBranchWithMain(branchName: string, strategy: 'rebase' | 'merge') {
  execSync(`git checkout ${branchName}`);
  execSync('git fetch origin');
  if (strategy === 'rebase') {
    execSync('git rebase origin/main', { stdio: 'inherit' });
  } else {
    execSync('git merge --no-ff origin/main', { stdio: 'inherit' });
  }
}

import { execSync } from 'node:child_process';

/**
 * QUY TRÌNH GIẢI QUYẾT XUNG ĐỘT (MERGE CONFLICT) AN TOÀN TUYỆT ĐỐI:
 *
 * 1. Tạo nhánh backup trước khi bắt đầu merge:
 *    git branch backup-before-merge
 *
 * 2. Bắt đầu merge nhánh main:
 *    git merge origin/main
 *    -> Xung đột: <<<<<<< HEAD (code của bạn) ======= >>>>>>> origin/main (code đồng đội)
 *
 * 3. Trao đổi với đồng đội để hiểu đúng ngữ nghĩa logic refactor mới.
 * 4. Chỉnh sửa file, loại bỏ conflict markers.
 * 5. Chạy test suite và linter kiểm tra toàn vẹn hệ thống:
 *    npm run lint && npm test
 *
 * 6. Stage file và hoàn tất commit:
 *    git add src/services/api.ts
 *    git commit -m "merge: resolve refactoring conflicts in api service"
 */

export function verifyConflictResolution() {
  // Kiểm tra không còn sót bất kỳ conflict markers nào trong toàn bộ dự án
  execSync('git diff --check', { stdio: 'inherit' });
  // Chạy tests trước khi cho phép commit
  execSync('npm test', { stdio: 'inherit' });
}

import { execSync } from 'node:child_process';

/**
 * HOÀN TÁC COMMIT TRÊN PUBLIC BRANCH (MAIN) AN TOÀN: REVERT VS RESET
 *
 * 1. TRÊN PUBLIC BRANCH (Đã push lên remote / CI/CD):
 *    BẮT BUỘC DÙNG `git revert` để tạo commit mới đảo ngược thay đổi:
 *    git checkout main
 *    git pull origin main
 *    git revert <bad-commit-hash> --no-edit
 *    git push origin main  (AN TOÀN TUYỆT ĐỐI, KHÔNG CẦN FORCE PUSH!)
 *
 * 2. TRÊN LOCAL BRANCH (Chưa từng push lên remote):
 *    Có thể dùng `git reset`:
 *    git reset --soft HEAD~1  (Giữ lại code trong Staging để sửa)
 *    git reset --hard HEAD~1  (Xóa sổ vĩnh viễn thay đổi - Cẩn trọng!)
 */

export function rollbackPublicCommit(commitHash: string) {
  // Tạo commit mới đảo ngược, giữ nguyên lịch sử cho cả team
  execSync(`git revert ${commitHash} --no-edit`, { stdio: 'inherit' });
  execSync('git push origin main', { stdio: 'inherit' });
}

