// MINH HỌA GIẢI MÃ JWT PAYLOAD PHÍA CLIENT (KHÔNG CẦN SECRET KEY!)
export function decodeJwtPayload(jwtToken: string): Record<string, unknown> {
  try {
    // 1. Phân tách 3 phần: Header, Payload, Signature
    const parts = jwtToken.split('.');
    if (parts.length !== 3) {
      throw new Error('Định dạng JWT không hợp lệ');
    }

    // 2. Phần thứ 2 là Payload chỉ bị Base64Url mã hóa, giải mã cực kỳ dễ dàng:
    const base64Url = parts[1];
    const base64 = base64Url.replace(/-/g, '+').replace(/_/g, '/');
    const jsonPayload = decodeURIComponent(
      atob(base64)
        .split('')
        .map((c) => '%' + ('00' + c.charCodeAt(0).toString(16)).slice(-2))
        .join('')
    );

    return JSON.parse(jsonPayload);
  } catch (error) {
    console.error('Không thể giải mã JWT:', error);
    return {};
  }
}

