// const payload = decodeJwtPayload(token);
// const isExpired = (payload.exp as number) * 1000 < Date.now();

let isRefreshing = false;
let failedQueue: Array<{
  resolve: (token: string) => void;
  reject: (err: unknown) => void;
}> = [];

const processQueue = (error: unknown, token: string | null = null) => {
  failedQueue.forEach((prom) => {
    if (error) prom.reject(error);
    else prom.resolve(token!);
  });
  failedQueue = [];
};

export async function authenticatedFetch(url: string, options: RequestInit = {}): Promise<Response> {
  let response = await fetch(url, options);

  // Nếu token hết hạn (401 Unauthorized)
  if (response.status === 401) {
    if (isRefreshing) {
      // Nếu đang có 1 tiến trình refresh chạy dở -> Xếp hàng đợi
      return new Promise<string>((resolve, reject) => {
        failedQueue.push({ resolve, reject });
      }).then((newToken) => {
        // Retry lại request ban đầu với Access Token mới
        const headers = new Headers(options.headers);
        headers.set('Authorization', `Bearer ${newToken}`);
        return fetch(url, { ...options, headers });
      });
    }

    isRefreshing = true;
    try {
      // Gọi API refresh ngầm (Cookie HttpOnly tự động gửi kèm)
      const refreshRes = await fetch('/api/auth/refresh', { method: 'POST' });
      if (!refreshRes.ok) throw new Error('Refresh token hết hạn, yêu cầu đăng nhập lại.');

      const { accessToken } = await refreshRes.json();
      processQueue(null, accessToken);

      // Gửi lại chính request bị lỗi ban đầu
      const retryHeaders = new Headers(options.headers);
      retryHeaders.set('Authorization', `Bearer ${accessToken}`);
      return await fetch(url, { ...options, headers: retryHeaders });
    } catch (refreshErr) {
      processQueue(refreshErr, null);
      window.location.href = '/login?expired=true';
      throw refreshErr;
    } finally {
      isRefreshing = false;
    }
  }

  return response;
}
